INSERT INTO topic_prerequisites SELECT (SELECT id FROM topics WHERE slug='two-pointers'),(SELECT id FROM topics WHERE slug='searching') WHERE NOT EXISTS (SELECT 1 FROM topic_prerequisites WHERE topic_id=(SELECT id FROM topics WHERE slug='two-pointers') AND prerequisite_id=(SELECT id FROM topics WHERE slug='searching'));
INSERT INTO topic_prerequisites SELECT (SELECT id FROM topics WHERE slug='sliding-window'),(SELECT id FROM topics WHERE slug='two-pointers') WHERE NOT EXISTS (SELECT 1 FROM topic_prerequisites WHERE topic_id=(SELECT id FROM topics WHERE slug='sliding-window') AND prerequisite_id=(SELECT id FROM topics WHERE slug='two-pointers'));
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Index access/update O(1); insertion/deletion O(n); storage O(n).','Valid indices lie in [0,n); insert permits index n. Shifts preserve the order of other elements.' FROM algorithms WHERE slug='arrays' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n) time, O(1) extra space.','All indices before the cursor have been checked; the first match is returned.' FROM algorithms WHERE slug='linear-search' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(log n) time, O(1) extra space.','If a target is present, it remains in the inclusive [lo,hi] interval.' FROM algorithms WHERE slug='binary-search' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n²) worst/average time, O(n) best time, O(1) extra space.','Before iteration i, the prefix [0,i) is sorted. Equal elements are not shifted past one another.' FROM algorithms WHERE slug='insertion-sort' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n log n) time, O(n) auxiliary space.','Each pass merges adjacent sorted runs of width w into sorted runs of width 2w.' FROM algorithms WHERE slug='merge-sort' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n log n) average, O(n²) worst time; O(n) bounded explicit range stack.','Within a partition, values before the boundary are ≤ pivot; later scanned values are > pivot.' FROM algorithms WHERE slug='quick-sort' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n) indexed insert/delete/search/traverse; O(1) relinking after the predecessor is located. O(n) space.','The head reaches each active node once; the last next ID is 0 (null). Node IDs remain stable during an operation.' FROM algorithms WHERE slug='linked-list' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Push/pop/peek O(1); O(n) storage.','The top is the last occupied element; only the top is removed.' FROM algorithms WHERE slug='stack' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Enqueue/inspect O(1); dequeue O(n) in this compact shifting implementation; O(n) storage.','The front is index 0; dequeue preserves the relative order of the remaining values.' FROM algorithms WHERE slug='queue' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Search/insert/delete O(h); traversals O(n). h may be n in an unbalanced tree; O(n) storage.','All left descendants are strictly smaller and all right descendants strictly larger. Duplicate inserts are ignored.' FROM algorithms WHERE slug='bst' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Adjacency-matrix edge lookup O(1); node removal O(V²); space O(V²).','Node IDs are unique; undirected edges are symmetric. Parallel edges replace their previous weight; self-loops are allowed.' FROM algorithms WHERE slug='graph' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(V²) with this adjacency matrix; O(V) frontier/visited space.','Vertices are marked on enqueue, so each reachable vertex enters the queue once.' FROM algorithms WHERE slug='bfs' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(V²) with this adjacency matrix; O(V) explicit stack space.','Each active stack path follows graph edges; marked vertices are never entered twice.' FROM algorithms WHERE slug='dfs' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(V²) time using linear minimum selection; O(V) distance/visited space.','The selected unsettled vertex has minimum tentative distance. With nonnegative edges its distance is final.' FROM algorithms WHERE slug='dijkstra' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 15,(SELECT id FROM lessons WHERE slug='hash-tables'),'hash-chain','Separate chaining' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='hash-chain');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Expected O(1) under distribution/load assumptions; O(n) worst case; rehash O(n+capacity).','Distinct keys survive collisions; equal keys update. Tombstones do not terminate probing.' FROM algorithms WHERE slug='hash-chain' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 16,(SELECT id FROM lessons WHERE slug='hash-tables'),'hash-probe','Linear probing' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='hash-probe');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Expected O(1) under distribution/load assumptions; O(n) worst case; rehash O(n+capacity).','Distinct keys survive collisions; equal keys update. Tombstones do not terminate probing.' FROM algorithms WHERE slug='hash-probe' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 17,(SELECT id FROM lessons WHERE slug='heaps'),'heaps','Heaps and Priority Queues' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='heaps');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Build O(n); existing-heap insert/extract O(log n), peek O(1); heap sort O(n log n). Runs include construction.','Every parent has priority at least as high as its children; the active prefix is complete.' FROM algorithms WHERE slug='heaps' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 18,(SELECT id FROM lessons WHERE slug='recursion'),'recursion','Recursive examples' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='recursion');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','Factorial/sum O(n) work and stack; search O(log n); Fibonacci exponential calls with O(n) stack.','Each child call decreases n or the search interval; a return pops exactly one frame.' FROM algorithms WHERE slug='recursion' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 19,(SELECT id FROM lessons WHERE slug='two-pointers'),'two-pointers','Two Pointers' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='two-pointers');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n) time, O(1) auxiliary space; sorting preparation is separate.','Only proved-impossible endpoints are discarded; the unique prefix contains each seen distinct value once.' FROM algorithms WHERE slug='two-pointers' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithms(id,lesson_id,slug,title) SELECT 20,(SELECT id FROM lessons WHERE slug='sliding-window'),'sliding-window','Sliding Window' WHERE NOT EXISTS (SELECT 1 FROM algorithms WHERE slug='sliding-window');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT id,'1.2.0','1.2.0','O(n) time and O(1) auxiliary space with monotone endpoints.','The running sum equals the half-open contiguous window; variable shrinking assumes nonnegative values.' FROM algorithms WHERE slug='sliding-window' AND NOT EXISTS (SELECT 1 FROM algorithm_versions WHERE algorithm_id=algorithms.id AND version='1.2.0');
INSERT INTO algorithm_versions(algorithm_id,version,engine_version,complexity,invariants) SELECT a.id,'1.1.0','1.1.0',old.complexity,old.invariants FROM algorithms a JOIN algorithm_versions old ON old.algorithm_id=a.id AND old.version='1.0.0' WHERE NOT EXISTS (SELECT 1 FROM algorithm_versions current WHERE current.algorithm_id=a.id AND current.version='1.1.0');
